CREATE OR REPLACE VIEW reporting.vw_dtc_detail AS SELECT r.report_id,r.file_id,r.file_name,r.vin,r.sw_i_step,r.sa_codes,d.dtc_event_id,d.ecu_name,e.hardware_version,e.bootloader_version,e.sw_version,e.coding,e.diagnostic_address,e.calibration_version,e.network,e.secure_boot,e.ota_state,d.dtc_code,d.description,d.fault_category,d.status,d.occurrence_counter,d.aging_counter,d.priority,d.event_timestamp,d.risk_score,CASE WHEN d.risk_score>300 THEN 'High' WHEN d.risk_score>200 THEN 'Medium' ELSE 'Low' END risk_band FROM raw.diagnostic_report r JOIN raw.dtc_event d ON d.report_id=r.report_id LEFT JOIN raw.ecu_version e ON e.report_id=r.report_id AND e.ecu_name=d.ecu_name;
CREATE OR REPLACE VIEW reporting.vw_environment_signal_detail AS SELECT r.sw_i_step,r.file_name,d.dtc_event_id,d.ecu_name,d.dtc_code,d.status,d.event_timestamp,s.environment_signal_id,s.signal_name,s.signal_value,s.numeric_signal_value FROM raw.environment_signal s JOIN raw.dtc_event d ON d.dtc_event_id=s.dtc_event_id JOIN raw.diagnostic_report r ON r.report_id=d.report_id;
CREATE OR REPLACE VIEW reporting.vw_pipeline_status AS SELECT f.file_id,f.file_name,f.sw_i_step,f.process_status,f.processing_start_time,f.processing_end_time,f.error_message,p.process_run_id,p.dtc_records_loaded,p.environment_records_loaded FROM admin.file_inventory f LEFT JOIN admin.process_execution_log p ON p.file_id=f.file_id;
